<?php
$rows=ak_bells();$isAdmin=current_user()['role']==='admin';
$classes=ak_rows("SELECT * FROM kelas WHERE status='aktif' ORDER BY (nama_kelas REGEXP '^(X|XI|XII) (PPLG|AKL|PM|MPLB) [1-3]$') DESC,FIELD(tingkat,'X','XI','XII'),nama_kelas");
$selected=($_GET['id_kelas']??'')!==''?input_id($_GET,'id_kelas'):null;$options=[];foreach($classes as $class)$options[$class['id_kelas']]=$class['nama_kelas'];
if($selected!==null&&!isset($options[$selected]))throw new InputError('Kelas tidak tersedia.');
$edit=null;if(isset($_GET['edit_jam'])){require_role('admin');$edit=ak_one('SELECT * FROM ak_jam_belajar WHERE id=?',[input_id($_GET,'edit_jam')]);if(!$edit)not_found();}
?><section class="panel"><h2>Hari dan waktu belajar<?= $selected?' · '.e($options[$selected]):''?></h2><p>Jam umum sekolah untuk semua kelas. Guru melihat acuan yang sama. Perubahan membuat versi baru; jadwal guru, absensi, dan jurnal yang sudah tersimpan tetap memakai konteks historisnya.</p>
<form method="get" class="form-grid"><?php ak_hidden('view','jam');ak_select('id_kelas','Tampilkan untuk kelas',$options,$selected??'',false);?><button class="secondary">Tampilkan</button></form>
<?php if($isAdmin):?><div class="actions"><a class="button secondary" href="/admin/master.php?table=kelas">Kelola kelas</a><a class="button secondary" href="<?=e(ak_link('kenaikan'))?>">Naik kelas</a></div><p class="muted">Gunakan Ubah Jam pada pola hari yang ingin disesuaikan. Baris tanpa nomor adalah kegiatan / istirahat.</p><?php endif;?></section>
<?php if($edit):$profile=json_decode($edit['payload_json'],true,512,JSON_THROW_ON_ERROR);?>
<section class="panel"><h2>Ubah Jam · <?=e($edit['nama'])?></h2><p>Versi <?=e($edit['versi'])?>. Semua kelas menggunakan pola umum ini; periksa seluruh rentang sebelum menyimpan.</p>
<form method="post" data-bell-editor><?=csrf_field()?><?php ak_hidden('action','jam_belajar');ak_hidden('id',$edit['id']);ak_hidden('revision',$edit['versi']);?>
<div data-bell-rows><?php foreach($profile['slots']as $i=>[$number,$from,$until,$label]):?>
<fieldset class="bell-edit-row"><legend>Baris <?=$i+1?></legend><div class="form-grid"><?php ak_field("slots[$i][nomor]",'Jam ke (kosong = kegiatan)',$number??'','number',false);ak_field("slots[$i][mulai]",'Mulai',$from,'time');ak_field("slots[$i][selesai]",'Selesai',$until,'time');ak_field("slots[$i][keterangan]",'Keterangan',$label);?></div><button type="button" class="secondary" data-remove-bell>Hapus baris</button></fieldset>
<?php endforeach;?></div><button type="button" class="secondary" data-add-bell>Tambah baris</button>
<?php ak_select('status','Status pemeriksaan',['referensi'=>'Referensi — sudah diperiksa Admin','perlu_konfirmasi'=>'Perlu konfirmasi'],$edit['status']);ak_textarea('catatan','Catatan jam',$edit['catatan'],true);ak_field('alasan','Alasan perubahan');?><label class="check"><input type="checkbox" name="terverifikasi" value="1"><span>Saya telah memeriksa seluruh jam. Wajib untuk status Referensi.</span></label>
<div class="actions"><button type="submit">Simpan Jam</button><a class="button secondary" href="<?=e(ak_link('jam',$selected?['id_kelas'=>$selected]:[]))?>">Batal</a></div></form></section>
<?php endif;?>
<div class="bell-grid"><?php foreach($rows as $row):$profile=json_decode($row['payload_json'],true,512,JSON_THROW_ON_ERROR);?><section class="panel"><h2><?=e($row['nama'])?> · versi <?=e($row['versi'])?></h2><p class="muted"><?=e($row['catatan'])?></p><?php if($row['status']==='perlu_konfirmasi'):?><div class="notice">Jam masih perlu konfirmasi Admin. Rentang dipertahankan tanpa diseragamkan otomatis.</div><?php endif;?><div class="table-scroll"><table class="bell-reference"><thead><tr><th>Jam ke</th><th>Waktu</th><th>Keterangan</th></tr></thead><tbody><?php foreach($profile['slots']as [$number,$from,$until,$label]):?><tr><td><?=e($number??'—')?></td><td><?=e($from)?>–<?=e($until)?></td><td class="wrap"><?=e($label)?></td></tr><?php endforeach;?></tbody></table></div>
<?php if($isAdmin):?><div class="actions"><a class="button" href="<?=e(ak_link('jam',['edit_jam'=>$row['id']]+($selected?['id_kelas'=>$selected]:[])))?>">Ubah Jam <?=e($row['nama'])?></a></div><?php endif;?></section><?php endforeach;?></div>
<?php if($isAdmin):$total=(int)ak_query('SELECT COUNT(*) FROM ak_jam_belajar')->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);?><section class="panel"><h2>Riwayat versi jam</h2><div class="table-scroll"><table><thead><tr><th>Hari</th><th>Versi</th><th>Waktu simpan</th><th>Admin</th><th>Alasan</th></tr></thead><tbody><?php foreach(ak_rows("SELECT b.*,u.username,r.alasan FROM ak_jam_belajar b JOIN users u ON u.id_user=b.created_by LEFT JOIN ak_riwayat r ON r.entity='jam_belajar' AND r.record_id=CAST(b.id AS CHAR) ORDER BY b.id DESC LIMIT 20 OFFSET $offset")as $history):?><tr><td><?=e($history['nama'])?></td><td><?=e($history['versi'])?></td><td><?=e($history['created_at'])?></td><td><?=e($history['username'])?></td><td class="wrap"><?=e($history['alasan']??'Referensi awal dari gambar')?></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></section><?php endif;?>
